    # Find a row where one color forms an uninterrupted run at the left and
    # another color immediately follows it. Extend that run through the suffix,
    # recoloring the suffix 1. This encodes the incomplete stripe in the demos.
    for r, row in enumerate(grid):
        if len(set(row)) < 2:
            continue
        bg = max(set(row), key=row.count)
        fg_candidates = [v for v in set(row) if v != bg]
        if not fg_candidates:
            continue
        fg = fg_candidates[0]
        c = 0
